:root {
  --p-color-bg-surface: #fff;
  --p-color-bg-surface-secondary: #f6f6f7;
  --p-color-bg-surface-tertiary: #e1e3e5;
  --p-color-bg-fill-brand: #008060;
  --p-color-bg-fill-brand-hover: #006e52;
  --p-color-bg-fill-brand-active: #005e46;
  --p-color-bg-fill-info: #5c6ac4;
  --p-color-bg-fill-success: #008060;
  --p-color-bg-fill-warning: #ffb900;
  --p-color-bg-fill-critical: #d72c0d;
  --p-color-text: #202223;
  --p-color-text-secondary: #6d7175;
  --p-color-text-disabled: #8c9196;
  --p-color-border: #c9cccf;
  --p-color-border-secondary: #e1e3e5;
  --p-shadow-card: 0 1px 0 0 #0000000d;
  --p-shadow-card-hover: 0 2px 4px #0000001a;
  --p-shadow-popover: 0 4px 8px #0000001a;
  --p-shadow-modal: 0 8px 16px #00000026;
  --p-space-1: 4px;
  --p-space-2: 8px;
  --p-space-3: 12px;
  --p-space-4: 16px;
  --p-space-5: 20px;
  --p-space-6: 24px;
  --p-border-radius-base: 8px;
  --p-border-radius-large: 12px;
  --p-font-family-sans: "Inter", -apple-system, BlinkMacSystemFont, "San Francisco", "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--p-font-family-sans);
  background-color: var(--p-color-bg-surface-secondary);
  color: var(--p-color-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.stat-card {
  background: var(--p-color-bg-surface);
  border: 1px solid var(--p-color-border-secondary);
  border-radius: var(--p-border-radius-base);
  padding: var(--p-space-4);
  box-shadow: var(--p-shadow-card);
  transition: all .2s;
}

.stat-card:hover {
  box-shadow: var(--p-shadow-card-hover);
  border-color: var(--p-color-border);
}

.card-elevated {
  background: var(--p-color-bg-surface);
  border-radius: var(--p-border-radius-large);
  border: 1px solid #0000000d;
  box-shadow: 0 2px 8px #00000014;
}

.btn-primary {
  background: var(--p-color-bg-fill-brand);
  color: #fff;
  cursor: pointer;
  border: none;
  border-radius: 6px;
  padding: 10px 20px;
  font-weight: 500;
  transition: background .2s;
}

.btn-primary:hover {
  background: var(--p-color-bg-fill-brand-hover);
}

.btn-primary:active {
  background: var(--p-color-bg-fill-brand-active);
}

.status-badge-success {
  color: #004c3f;
  background: #d4f4dd;
  border-radius: 4px;
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 500;
}

.status-badge-warning {
  color: #7f4f00;
  background: #fff4e5;
  border-radius: 4px;
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 500;
}

.status-badge-info {
  color: #2c3e8f;
  background: #e3e7ff;
  border-radius: 4px;
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 500;
}

.transition-smooth {
  transition: all .3s cubic-bezier(.4, 0, .2, 1);
}

.skeleton {
  background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%) 0 0 / 200% 100%;
  animation: 1.5s infinite loading;
}

@keyframes loading {
  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }
}

.chart-container {
  border-radius: var(--p-border-radius-base);
  padding: var(--p-space-4);
  background: #fff;
}

.Polaris-Card {
  border: 1px solid #0000000f !important;
  border-radius: 12px !important;
  box-shadow: 0 1px 3px #00000014 !important;
}

.Polaris-Page {
  max-width: 100% !important;
  padding: 24px 32px !important;
}

.Polaris-Button--primary {
  background: linear-gradient(#008060 0%, #006e52 100%) !important;
  box-shadow: 0 2px 4px #00806033 !important;
}

.Polaris-Button--primary:hover {
  background: linear-gradient(#006e52 0%, #005e46 100%) !important;
  box-shadow: 0 4px 8px #00806040 !important;
}

